// Déplacement + caméra d'épaule, sans arme — prefab par défaut « Troisième personne ».
// Même convention que le prefab FPS (fps-controller.prefab.json) : le joueur ne connaît que
// le CAP de CameraRig, jamais sa matrice monde.
//
// @expose speed {number} = 6
// @expose sprintSpeed {number} = 10
// @expose jumpForce {number} = 9
// @expose gravity {number} = 24
// @expose turnSpeed {number} = 12

function update(api){
  var e = api.expose;
  var rig = api.find('CameraRig');
  var camYaw = rig ? rig.rotation.y : api.me.rotation.y;

  var da = Math.atan2(Math.sin(camYaw - api.me.rotation.y), Math.cos(camYaw - api.me.rotation.y));
  api.me.rotation.y += da * Math.min(1, api.dt * e.turnSpeed);

  var sprinting = api.action('sprint');
  api.moveCharacter({
    speed: sprinting ? e.sprintSpeed : e.speed,
    jump: e.jumpForce,
    gravity: e.gravity,
    tagGround: 'ground',
    yaw: camYaw
  });
}

