scripts.code:
// Le BRAS de caméra d'épaule : orbite à la souris autour du joueur, recul horizontal contre
// le décor. C'EST LE BRAS QUI TOURNE (cap ET tangage) — PAS la caméra elle-même : « Camera »,
// son enfant, reste à un décalage LOCAL fixe (0, 0, -distance) sans jamais toucher à sa propre
// rotation. Voir jeux/TPS/src/tps-camera.js pour la version commentée en détail.
//
// @expose distance {number} = 5
// @expose sensitivity {number} = 0.0025
// @expose minPitch {number} = -0.6
// @expose maxPitch {number} = 0.9
// @expose collisionMargin {number} = 0.3

var yaw = 0, pitch = 0.15;
var cam = null;

function start(api){
  cam = api.find('Camera');
  api.lockMouse(true);
}

function update(api){
  var e = api.expose;
  if(!api.mouseLocked() && api.click(0)) api.lockMouse(true);

  var md = api.mouseDelta();
  yaw -= md.x * e.sensitivity;
  pitch = Math.max(e.minPitch, Math.min(e.maxPitch, pitch - md.y * e.sensitivity));
  // NÉGATION VOULUE sur X (même piège qu'en FPS) : pitch > 0 = regarder en haut, mais une
  // rotation de +a autour de X emmène le +Z d'un nœud vers le BAS. Le BRAS reçoit -pitch.
  api.me.rotation.set(-pitch, yaw, 0);
  if(!cam) return;

  var origin = api.me.position;
  var back = {x: -Math.sin(yaw), y: 0, z: -Math.cos(yaw)};
  var hit = api.raycast(origin, back, e.distance + e.collisionMargin, {tag: 'ground'});
  var dist = hit ? Math.max(0.5, hit.distance - e.collisionMargin) : e.distance;
  cam.position.set(0, 0, -dist);
}

